def transform(grid):
    """Move the non-background pattern down one row, clipping the bottom."""
    if not grid:
        return []
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    width = len(grid[0])
    return [[background] * width] + [list(row) for row in grid[:-1]]
